package io.github.diodeme.ji.provider.anthropic;

import io.github.diodeme.ji.ai.CredentialResolver;
import io.github.diodeme.ji.ai.ModelProvider;
import io.github.diodeme.ji.ai.ModelRequest;
import io.github.diodeme.ji.ai.ModelResponse;
import io.github.diodeme.ji.ai.ModelStreamEvent;
import io.github.diodeme.ji.ai.ProviderProfile;
import io.github.diodeme.ji.ai.ProviderProtocolFamily;
import io.github.diodeme.ji.provider.http.HttpModelProvider;
import io.github.diodeme.ji.provider.http.ProviderEndpoints;
import java.net.URI;
import java.util.concurrent.CompletionStage;
import java.util.concurrent.Flow;

/** Anthropic Messages protocol adapter. */
public final class AnthropicProvider implements ModelProvider {
    private final HttpModelProvider delegate;

    public AnthropicProvider(ProviderProfile profile, CredentialResolver credentials) {
        if (profile.family() != ProviderProtocolFamily.ANTHROPIC) {
            throw new IllegalArgumentException("profile family must be anthropic");
        }
        delegate = new HttpModelProvider(profile, credentials, new AnthropicWireAdapter());
    }

    public static URI normalizeEndpoint(String baseUrl) {
        return ProviderEndpoints.v1(URI.create(baseUrl), "messages");
    }

    public URI endpoint() { return ProviderEndpoints.v1(delegate.profile().baseUrl(), "messages"); }
    @Override public Flow.Publisher<ModelStreamEvent> stream(ModelRequest request) { return delegate.stream(request); }
    @Override public CompletionStage<ModelResponse> complete(ModelRequest request) { return delegate.complete(request); }
    @Override public CompletionStage<Void> closeAsync() { return delegate.closeAsync(); }
}
